function url(lang,path='',query=''){return '/'+lang+'/'+path+query}
function layout(lang,title,body,u){const t=messages[lang],base=u.pathname.replace(new RegExp('^/('+Object.keys(locales).join('|')+')/'),'/');return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="${u.hostname==='cnshoppergrid.com'&&!u.searchParams.has('q')?'index,follow':'noindex,follow'}"><link rel="canonical" href="${u.origin}${esc(u.pathname)}${esc(u.search)}">${Object.keys(locales).map(k=>`<link rel="alternate" hreflang="${k}" href="${u.origin}/${k}${esc(base)}${esc(u.search)}">`).join('')}<link rel="alternate" hreflang="x-default" href="${u.origin}/en${esc(base)}${esc(u.search)}"><title>${esc(title)} | CNShopper Grid</title><meta name="description" content="${esc(t[7])}"><link rel="icon" href="/favicon.ico?v=2"><style>${css}${extraCSS}${compactCSS}.brand img{object-fit:contain}.pagination-full{margin:32px 0}.page-summary{text-align:center;font-weight:700;margin:12px}.page-numbers{display:flex;flex-wrap:wrap;gap:6px;max-height:210px;overflow-y:auto;padding:12px;border:1px solid #e5e5e5;border-radius:8px}.page-numbers a{padding:8px 12px;border:1px solid #ddd;border-radius:4px;min-width:40px;text-align:center}.page-numbers [aria-current]{background:#f4c32f;border-color:#f4c32f;font-weight:bold}.page-jump{display:flex;gap:16px;align-items:center;justify-content:center;flex-wrap:wrap;margin:18px 0}.page-jump input{width:90px;padding:10px;border:1px solid #ccc;border-radius:4px}.page-jump button{padding:10px 16px;background:#f4c32f;border:0;border-radius:4px}.source-gallery,.qc-section{max-width:1120px;margin:30px auto;border-top:1px solid #eee;padding-top:22px}.detail-photos{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;max-height:440px;overflow:auto}.detail-photos img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px}.style-empty{min-height:110px;max-height:240px;overflow:auto;background:#fafafa;padding:16px;border:1px solid #e5e5e5;border-radius:10px;font-size:13px;line-height:1.7}.brand img{width:140px;height:auto;padding:0;filter:none}.detail .mainphoto{max-height:520px;object-fit:contain}.detail .thumbs{display:none}@media(max-width:650px){.detail-photos{grid-template-columns:repeat(3,minmax(0,1fr))}.page-numbers{max-height:155px}.page-jump{gap:9px}.page-jump a{font-size:12px}}</style></head><body><header><div class="nav"><a class="brand" href="/${lang}/"><img src="/logo.png" alt="CNShopper"></a><nav><a href="/${lang}/">${t[0]}</a><a href="/${lang}/spreadsheet/">${t[1]}</a><a href="/${lang}/categories/">${t[2]}</a><a href="/${lang}/image-search/">${ui(lang,'imageSearch')}</a><a href="/${lang}/guide/">${t[3]}</a></nav><div class="tools"><details class="language-menu" id="language-menu"><summary aria-label="${ui(lang,'language')}">◎ ${locales[lang]} <span>⌄</span></summary><div class="language-options">${Object.entries(locales).map(([k,v])=>`<a href="/${k}${esc(base)}${esc(u.search)}" lang="${k}" hreflang="${k}" ${k===lang?'aria-current="true"':''}>${v}</a>`).join('')}</div></details><select id="currency" aria-label="${ui(lang,'currency')}">${['USD','EUR','GBP','CNY','JPY','KRW','CAD','AUD','CHF','PLN','BRL'].map(c=>`<option>${c}</option>`).join('')}</select><a class="join" href="https://cnshopper.com/register" target="_blank" rel="noopener">${t[4]} →</a></div></div></header><main class="wrap">${body}<footer class="foot"><a class="brand" href="/${lang}/"><img src="/logo.png" alt="CNShopper"></a><p class="small">${t[32]}<br>${t[24]}</p><span class="small">© 2026 CNShopper Grid</span></footer></main><script id="page-config" type="application/json">${JSON.stringify({lang,labels:labelObject(lang),sourceLabels:messages[lang]}).replace(/</g,'\u003c')}</script><script src="/app-v2.js" defer></script></body></html>`}
function name(n,l,path=''){if(l==='en')return n;return localizedTitle(n,l,path)}

function search(l,q=''){let t=messages[l];return `<form class="search" action="/${l}/spreadsheet/"><input aria-label="${t[8]}" name="q" placeholder="${t[8]}" value="${esc(q)}"><a class="camera" href="/${l}/image-search/" aria-label="${ui(l,'imageSearch')}">${camera}</a><button>${t[9]} →</button></form>`}
function chips(l,current='AllProducts'){return `<div class="chips">${cats.map((c,i)=>`<a class="chip ${c===current?'active':''}" href="/${l}/spreadsheet/?category=${c}">${messages[l][13].split('|')[i]}</a>`).join('')}</div>`}
function card(p,l){const path=`/${l}/product${p.path}`;return `<article class="card"><a class="photo" href="${esc(path)}"><img src="${esc(p.image)}" alt="${esc(name(p.name,l,p.path||path))}" loading="lazy"><span class="arrow">→</span></a><div class="cardmeta"><span>${esc(messages[l][13].split('|')[cats.indexOf(p.path.split('/')[1])]||'CNSHOPPER')}</span><span>→</span></div><a href="${esc(path)}"><h3>${esc(name(p.name,l,p.path||path))}</h3></a>${p.price?`<div class="price" data-usd="${esc(p.price)}">$${esc(p.price)} USD</div>`:''}</article>`}
