function localizedTitle(n,l,path=''){
 const idx=languageOrder.indexOf(l);if(l==='en')return n;
 if(idx<0){let category=path.split('/').find(x=>cats.includes(x));let type=messages[l][13].split('|')[Math.max(0,cats.indexOf(category))];const kind=TYPE_KEYS.findIndex(k=>new RegExp('\\b(?:'+k+')\\b','i').test(n));if(kind>=0)type=TYPE_NAMES[l]?.split('|')[kind]||type;const identities=[...new Set([...(n.match(brands)||[]),...(n.match(/\b(?:[A-Z]{1,4}\d+[A-Za-z\d.\-]*|\d{2,4}[A-Z]{1,3})\b/g)||[])])].join(' ');return (identities?identities+' — ':'')+type;}
 let held=[];let work=dec(n).replace(brands,m=>{held.push(m);return '§'+(held.length-1)+'§'});
 const models=[];work=work.replace(/\b(?:[A-Z]{1,4}\d+[A-Za-z\d.\-]*|\d{2,4}[A-Z]{1,3})\b/g,m=>{models.push(m);return '¤'+(models.length-1)+'¤'});
 let translated=0;const values=[];
 for(const row of titleDictionary){let reg=new RegExp('\\b'+row[0].replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','gi');work=work.replace(reg,()=>{translated++;values.push(row[idx]);return '¶'+(values.length-1)+'¶'})}
 // Untranslated descriptive phrases are not disguised as a finished translation.
 const unresolved=work.replace(/[§¤¶]\d+[§¤¶]/g,'').replace(/\b(?:x|s|for|of|the|a|an|in)\b/gi,'').replace(/[^A-Za-z]/g,'');
 let result=work.replace(/¶(\d+)¶/g,(_,i)=>values[i]).replace(/§(\d+)§/g,(_,i)=>held[i]).replace(/¤(\d+)¤/g,(_,i)=>models[i]).replace(/\s+/g,' ').trim();
 if(unresolved.length>0||translated===0){let cat=path.split('/').find(x=>cats.includes(x));let type=messages[l][13].split('|')[Math.max(0,cats.indexOf(cat))];const typeRow=titleDictionary.find(r=>/jacket|shirt|sneaker|shoe|boot|slipper|sandal|slide|bag|hoodie|sweater|sweatshirt|coat|puffer|windbreaker|jeans|pants|shorts|trouser|wallet|belt|hat|cap|beanie|watch|bracelet|necklace|ring|earring|glasses|scarf|sock|underwear|perfume|vest|jersey|tracksuit|suit|set|holder|case/.test(r[0])&&new RegExp('\\b'+r[0].replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(n));if(typeRow)type=typeRow[idx];const brandPart=[...new Set([...held,...models])].join(' ');result=(brandPart?brandPart+' — ':'')+type;}
 return result||n;
}

